mapper.select:
SELECT p.id, p.pay_no AS payNo, p.target_type AS targetType, p.target_id AS targetId, CASE WHEN p.target_type = '1' THEN s.supplier_name ELSE m.member_name END AS targetName, p.pay_date AS payDate, p.amount, p.pay_type AS payType, p.status, p.create_by AS createBy, p.create_time AS createTime, p.remark FROM jxc_payment p LEFT JOIN jxc_supplier s ON p.target_type = '1' AND p.target_id = s.id LEFT JOIN jxc_member m ON p.target_type = '2' AND p.target_id = m.id
AND p.pay_no LIKE CONCAT('%', #{payNo}, '%')
AND p.target_type = #{targetType}
AND p.target_id = #{targetId}
ORDER BY p.id DESC

SELECT id, pay_no AS payNo, target_type AS targetType, target_id AS targetId, pay_date AS payDate,
       amount, pay_type AS payType, status, create_by AS createBy, create_time AS createTime, remark
FROM jxc_payment WHERE id = #{id}

SELECT p.id, p.supplier_id AS supplierId, s.supplier_name AS supplierName, p.source_no AS sourceNo, p.source_type AS sourceType, p.amount, p.paid_amount AS paidAmount, p.balance, p.status, p.create_time AS createTime FROM jxc_payable p LEFT JOIN jxc_supplier s ON p.supplier_id = s.id
AND p.supplier_id = #{supplierId} AND p.status = #{status}
ORDER BY p.id DESC

SELECT r.id, r.member_id AS memberId, m.member_name AS memberName, m.phone, r.source_no AS sourceNo, r.source_type AS sourceType, r.amount, r.paid_amount AS paidAmount, r.balance, r.status, r.create_time AS createTime FROM jxc_receivable r LEFT JOIN jxc_member m ON r.member_id = m.id
AND r.member_id = #{memberId} AND r.status = #{status}
ORDER BY r.id DESC
